		state := serviceReleaseState{State: releasechannel.StateRolling, Actor: "ops", Digest: candidate.Digest,
			Previous: previous.Digest, Intent: &intent, IssuedAt: time.Now()}
		var revision uint64
		save := func(next serviceReleaseState) (err error) {
