// releaseLoadWriter models delivery of a new release to all three hosts.
// The real fence's restart permit still controls when each report changes.
type releaseLoadWriter struct {
	*fenceCell
	candidate, failNode string
	applied             []host.Desired
}

func (w *releaseLoadWriter) Plan(_ context.Context, intent delivery.Intent) ([]host.Desired, error) {
	var desired []host.Desired
	for _, node := range w.nodes {
		desired = append(desired, host.Desired{Cell: intent.Cell, Node: node, Role: intent.Role, Environment: intent.Environment,
			Digest: intent.ArtifactDigest, Generation: intent.Generation, AuthorityEpoch: intent.AuthorityEpoch})
	}
	return desired, nil
}

func (w *releaseLoadWriter) ApplyDesired(_ context.Context, desired host.Desired) (host.Receipt, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	w.applied = append(w.applied, desired)
	if generation := releaseOf(desired.Generation); generation != w.release {
		w.release, w.restarts = generation, nil
	}
	w.broken = map[string]bool{}
	if desired.Digest == w.candidate && w.failNode != "" {
		w.broken[w.failNode] = true
	}
	return host.Receipt{}, nil
}

func nativeIntent(record delivery.ArtifactRecord, release nativeRelease, generation uint64) delivery.Intent {
	profile := release.Profile
	return delivery.Intent{Source: record.Source, ArtifactDigest: record.Digest, ManifestDigest: record.ManifestDigest,
		Cell: record.Cell, Role: record.Role, Environment: record.Environment, Generation: generation, DesiredReplicas: release.Replicas,
		ConfigDigest: delivery.ConfigDigestOf(profile.Args, profile.Env, profile.Secrets)}
}

// roll submits intent and waits for its readiness gate. A release that
// fails the gate is rolled back to its persisted target, which must
// pass the same gate; roll then fails.
func (d nativeDeployer) roll(ctx context.Context, intent delivery.Intent, wait time.Duration, output io.Writer) error {
	if d.prepare == nil || d.observe == nil {
		return errors.New("native deployer requires signed profile preparation and verified observation")
	}
	good := d.target
	var rollback delivery.ArtifactRecord
	if !d.bound {
		var err error
		intent, good, err = d.prepare(ctx, intent, "", "")
		if err != nil {
			return fmt.Errorf("%s release %s did not reach the members: prepare native release before host changes: %w", intent.Role, intent.ArtifactDigest, err)
		}
	}
	if good != nil {
		rollback = good.Artifact
	}
	role, digest, generation := intent.Role, intent.ArtifactDigest, intent.Generation
	forwardIntent := intent
	previous := rollback.Digest
	changed, gateErr := d.rollOut(ctx, intent, wait, output)
	switch {
	case gateErr == nil:
		return nil
	case !changed:
		return fmt.Errorf("%s release %s did not reach the members: %w", role, digest, gateErr)
	case rollback.Digest == "":
		return fmt.Errorf("%s release %s failed its readiness gate and there is no previous digest to roll back to: %w", role, digest, gateErr)
	}
	intent.Source, intent.ArtifactDigest, intent.ManifestDigest = rollback.Source, rollback.Digest, rollback.ManifestDigest
	if good != nil {
		intent.ConfigDigest, intent.DesiredReplicas = good.ConfigDigest, good.Replicas
	}
	intent.OperationID, intent.AuthorityEpoch, intent.Generation = "", 0, generation+1
	// A rollback restores what served before; no canary gates it.
	d.canary = nil
	// A fresh context with its own deadline: the command's context may be
	// the one that expired or was interrupted.
	recoveryWait := rollout.ObservationBudget
	recovery, cancel := context.WithTimeout(context.Background(), recoveryWait+time.Minute)
	defer cancel()
	desired, err := d.hosts.ListDesired(recovery, role)
	if err != nil {
		return fmt.Errorf("%w: read committed rollback generation: %w", errRecoveryNotStarted, err)
	}
	intent.Generation = max(intent.Generation, nextReleaseGeneration(desired))
	if generation == ^uint64(0) || intent.Generation == 0 {
		return fmt.Errorf("%w: %w", errRecoveryNotStarted, workload.ErrGenerationSpace)
	}
	if d.recovering != nil {
		var err error
		if intent, err = d.recovering(recovery, intent, gateErr); err != nil {
			return fmt.Errorf("%s release %s failed its readiness gate (%w): %w: %w", role, digest, gateErr, errRecoveryNotStarted, err)
		}
	}
	if d.prepare != nil {
		var err error
		if intent, _, err = d.prepare(recovery, intent, forwardIntent.OperationID, ""); err != nil {
			return fmt.Errorf("%w: %w", errRecoveryNotStarted, err)
		}
	}
	if _, err := d.rollOut(recovery, intent, recoveryWait, output); err != nil {
		return fmt.Errorf("%s release %s failed its readiness gate (%w) and rollback to %s failed: %w: %w", role, digest, gateErr, previous, errRollbackUnfinished, err)
	}
	return fmt.Errorf("%s release %s failed its readiness gate and was rolled back to %s: %w", role, digest, previous, gateErr)
}

// submitTerraBaseIntent is submitIntent; tests replace it to lose a publish
// acknowledgement.
var submitTerraBaseIntent = submitIntent

// rollOut submits one release intent and waits for its readiness
// gate. changed reports whether the release may have written, or may still
// write, any member's desired; a rollback is due whenever it is set. A
// submit that failed before Submit was called published nothing. Any later
// submit error or an interrupt proves nothing, since the intent may have
// been published: the durable operation is read back, and only a receipt
// that proves no member changed clears changed. Read errors are retried
// until wait.
func (d nativeDeployer) rollOut(ctx context.Context, intent delivery.Intent, wait time.Duration, output io.Writer,
) (changed bool, _ error) {
	wait = min(wait, rollout.ObservationBudget)
	service := d.service
	if d.observe == nil {
		return false, errors.New("native release requires verified observation")
	}
	if wait <= 0 {
		// An expired persisted intent may already have changed members.
		return true, context.DeadlineExceeded
	}
	gateCtx, cancel := context.WithTimeout(ctx, wait)
	defer cancel()
	intent, fingerprint, submitErr := d.submit(gateCtx, intent)
	if submitErr != nil && fingerprint == "" {
		return false, submitErr
	}
	tick := time.NewTicker(time.Second)
	defer tick.Stop()
	accepted := false
	var last error
	for {
		if !accepted {
			receipt, err := service.StatusFor(gateCtx, intent)
			switch {
			case err != nil:
				last = err
			case receipt.Status == "accepted":
				accepted = true
				if err := printJSON(output, terraBaseReleaseStep{Step: "deploy", Digest: intent.ArtifactDigest, Generation: intent.Generation}); err != nil {
					return true, err
				}
				if d.sequence != nil {
					if err := d.sequence(gateCtx, intent, d.canary); err != nil {
						return true, err
					}
				}
			default:
				return !unchanged(receipt), errors.Join(submitErr, fmt.Errorf("delivery %s: %s", receipt.Status, receipt.Error))
			}
		}
		if accepted {
			ready, err := d.observe(gateCtx, intent)
			last = err
			if errors.Is(err, errBadRelease) {
				return true, err
			}
			if err == nil && ready {
				return true, printJSON(output, terraBaseReleaseStep{Step: "ready", Digest: intent.ArtifactDigest, Members: intent.DesiredReplicas})
			}
		}
		select {
		case <-gateCtx.Done():
			if accepted {
				return true, errors.Join(gateCtx.Err(), fmt.Errorf(
					"%s replicas did not report %s running within %s (last error: %v)", intent.Role, intent.ArtifactDigest, wait, last))
			}
			// Interrupted or undecided: read the stored outcome once more on a
			// fresh context. Without a receipt that proves no change, the
			// release may still land; the rollback's higher generation keeps
			// it from landing.
			readCtx, cancelRead := context.WithTimeout(context.Background(), 10*time.Second)
			receipt, err := service.StatusFor(readCtx, intent)
			cancelRead()
			undecided := fmt.Errorf("delivery of operation %s was not decided within %s (last error: %v)", intent.OperationID, wait, last)
			if err == nil && unchanged(receipt) {
				return false, errors.Join(submitErr, gateCtx.Err(), fmt.Errorf("delivery %s: %s", receipt.Status, receipt.Error))
			}
			return true, errors.Join(submitErr, gateCtx.Err(), undecided)
		case <-tick.C:
		}
	}
}

func nativeReady(statuses []host.HostStatus, desired []host.Desired, intent delivery.Intent, now time.Time) ([]string, error) {
	expected := map[string]host.Desired{}
	for _, d := range desired {
		if d.Cell != intent.Cell || d.Role != intent.Role || d.Environment != intent.Environment || d.Withdrawn {
			continue
		}
		if _, duplicate := expected[d.Node]; duplicate {
			return nil, errors.New("duplicate expected native node")
		}
		if d.Digest != intent.ArtifactDigest || d.Generation != intent.Generation && workload.ReleaseOf(d.Generation) != intent.Generation ||
			delivery.ConfigDigestOf(d.Args, d.Env, d.Secrets) != intent.ConfigDigest {
			return nil, nil
		}
		expected[d.Node] = d
	}
	if len(expected) != intent.DesiredReplicas || len(expected) == 0 {
		return nil, nil
	}
	seen := map[string]bool{}
	for _, status := range statuses {
		r := status.Registration
		d, ok := expected[r.Node]
		if !ok {
			continue
		}
		if seen[r.Node] {
			return nil, errors.New("duplicate native host status")
		}
		seen[r.Node] = true
		if !status.Verified || status.Retired || !status.SessionExpiresAt.After(now) || r.Cell != intent.Cell || r.Environment != intent.Environment || !slices.Contains(r.Roles, intent.Role) {
			return nil, nil
		}
		matches := 0
		for _, report := range status.Reports {
			if report.Role != intent.Role {
				continue
			}
			matches++
			if matches > 1 {
				return nil, errors.New("duplicate native report")
			}
			if report.Cell != intent.Cell || report.Node != d.Node || report.Environment != intent.Environment || report.Digest != d.Digest || report.Generation != d.Generation ||
				report.SessionID == "" || report.Epoch == 0 || report.ObservedAt.IsZero() || report.ObservedAt.After(now) || now.Sub(report.ObservedAt) >= host.ReportMaxAge {
				return nil, nil
			}
			if report.State == "failed" {
				return nil, fmt.Errorf("%w: %s replica %s failed: %s", errBadRelease, intent.Role, report.Node, report.Error)
			}
			if report.State != "running" {
				return nil, nil
			}
		}
		if matches != 1 {
			return nil, nil
		}
	}
	if len(seen) != len(expected) {
		return nil, nil
	}
	return slices.Sorted(maps.Keys(expected)), nil
}

func knownBadKey(role, digest string) string { return "knownbad." + role + "." + digest }

func knownBad(ctx context.Context, kv jetstream.KeyValue, role, digest string) (knownBadRecord, bool, error) {
	entry, err := kv.Get(ctx, knownBadKey(role, digest))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return knownBadRecord{}, false, nil
	}
	if err != nil {
		return knownBadRecord{}, false, err
	}
	var record knownBadRecord
	if err := json.Unmarshal(entry.Value(), &record); err != nil {
		return knownBadRecord{}, false, fmt.Errorf("decode %s: %w", entry.Key(), err)
	}
	return record, true, nil
}

func markKnownBad(ctx context.Context, kv jetstream.KeyValue, role, digest string, cause error) error {
	wire, err := json.Marshal(knownBadRecord{At: time.Now().UTC(), Reason: releasechannel.Clip(cause.Error())})
	if err != nil {
		return err
	}
	_, err = kv.Put(ctx, knownBadKey(role, digest), wire)
	return err
}

func saveServiceRelease(ctx context.Context, kv jetstream.KeyValue, key string, state serviceReleaseState, revision uint64) (uint64, error) {
	wire, err := json.Marshal(state, json.Deterministic(true))
	if err != nil {
		return 0, err
	}
	if revision == 0 {
		return kv.Create(ctx, key, wire)
	}
	return kv.Update(ctx, key, wire, revision)
}

func Open(ctx context.Context, cfg Config) (*Service, error) {
	if cfg.Conn == nil || cfg.JS == nil || !validCell(cfg.Cell) || cfg.Replicas != 1 && cfg.Replicas != 3 && cfg.Replicas != 5 || cfg.ArtifactStoreMaxBytes < 0 {
		return nil, fmt.Errorf("%w: delivery service configuration", ErrInvalid)
	}
	artifactStoreMaxBytes := cfg.ArtifactStoreMaxBytes
	if artifactStoreMaxBytes == 0 {
		artifactStoreMaxBytes = DefaultArtifactStoreMaxBytes
	}
	// A larger quota already in force came from the cell spec
	// (artifact_store), which the leader re-applies; a restart must not
	// shrink the store under an upload before then.
	if existing, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket); err == nil {
		artifactStoreMaxBytes = max(artifactStoreMaxBytes, existing.CachedInfo().Config.MaxBytes)
	} else if !errors.Is(err, jetstream.ErrStreamNotFound) {
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	s := &Service{js: cfg.JS, config: cfg}
	var err error
	s.artifacts, err = cfg.JS.CreateOrUpdateObjectStore(ctx, artifactStoreConfig(cfg.Replicas, artifactStoreMaxBytes))
	if err != nil {
		return nil, fmt.Errorf("artifact store: %w", err)
	}
	stream, err := cfg.JS.Stream(ctx, "OBJ_"+ArtifactBucket)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	streamInfo, err := stream.Info(ctx)
	if err != nil {
		if errors.Is(err, jetstream.ErrStreamNotFound) {
			return nil, fmt.Errorf("%w: inspect artifact store limits: %w", ErrStoreNotReady, err)
		}
		return nil, fmt.Errorf("inspect artifact store limits: %w", err)
	}
	if streamInfo.Config.MaxBytes != artifactStoreMaxBytes || streamInfo.Config.Discard != jetstream.DiscardNew {
		return nil, fmt.Errorf("%w: artifact store must enforce the configured byte quota with discard-new", ErrInvalid)
	}
	s.admissions, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: AdmissionBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 1})
	if err != nil {
		return nil, fmt.Errorf("artifact admissions: %w", err)
	}
	s.operations, err = cfg.JS.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: OperationBucket, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, History: 4})
	if err != nil {
		return nil, fmt.Errorf("delivery operations: %w", err)
	}
	_, err = cfg.JS.CreateOrUpdateStream(ctx, jetstream.StreamConfig{Name: IntentStream, Subjects: []string{IntentSubject(cfg.Cell)}, Storage: jetstream.FileStorage, Replicas: cfg.Replicas, Retention: jetstream.WorkQueuePolicy, Discard: jetstream.DiscardNew, MaxMsgs: 100_000, MaxBytes: 1 << 30, MaxMsgSize: MaxIntentBytes + 8192, Duplicates: 2 * time.Minute})
	if err != nil {
		return nil, fmt.Errorf("delivery intent stream: %w", err)
	}
	s.consumer, err = cfg.JS.CreateOrUpdateConsumer(ctx, IntentStream, intentConsumerConfig(cfg.Cell))
	if err != nil {
		return nil, fmt.Errorf("delivery intent consumer: %w", err)
	}
	return s, nil
}

func (s *Service) SubmitVerified(ctx context.Context, intent Intent, actor string) error {
	if s == nil || s.operations == nil || s.config.Authorize == nil || actor == "" {
		return errors.New("verified delivery submission is not configured")
	}
	if err := intent.Validate(); err != nil {
		return err
	}
	if intent.Cell != s.config.Cell {
		return fmt.Errorf("%w: wrong cell", ErrInvalid)
	}
	if err := s.config.Authorize(ctx, actor, intent.Clone()); err != nil {
		return err
	}
	wire, err := json.Marshal(intent)
	if err != nil {
		return err
	}
	if len(wire) > MaxIntentBytes {
		return fmt.Errorf("%w: intent too large", ErrInvalid)
	}
	fingerprint, err := intent.fingerprint()
	if err != nil {
		return err
	}
	verified, err := json.Marshal(struct {
		Intent Intent `json:"intent"`
		Actor  string `json:"actor"`
	}{intent, actor})
	if err != nil {
		return err
	}
	sum := sha256.Sum256(wire)
	if _, err := s.operations.Create(ctx, entityid.Derive("delivery-verified", hex.EncodeToString(sum[:])), verified); err != nil && !errors.Is(err, jetstream.ErrKeyExists) {
		return fmt.Errorf("record verified delivery intent: %w", err)
	}
	if err := s.publishIntent(ctx, IntentSubject(intent.Cell), wire, intent.OperationID+"."+fingerprint); err != nil {
		return fmt.Errorf("publish delivery intent: %w", err)
	}
	return nil

func (s *Service) getOperation(ctx context.Context, key string) (*operationValue, error) {
	if s == nil || s.config.Conn == nil {
		return nil, errors.New("delivery operation leader read requires NATS connection")
	}
	js, err := s.config.Conn.JetStream()
	if err != nil {
		return nil, err
	}
	subject := "$KV." + OperationBucket + "." + key
	msg, err := js.GetLastMsg("KV_"+OperationBucket, subject, nats.Context(ctx))
	if errors.Is(err, nats.ErrMsgNotFound) {
		return nil, jetstream.ErrKeyNotFound
	}
	if err != nil {
		return nil, err
	}
	return operationValueFromMsg(subject, msg)
}

func operationValueFromMsg(subject string, msg *nats.RawStreamMsg) (*operationValue, error) {
	if msg == nil || msg.Subject != subject || msg.Sequence == 0 {
		return nil, errors.New("invalid delivery operation state")
	}
	if operation := msg.Header.Get("KV-Operation"); operation != "" {
		if operation == "DEL" || operation == "PURGE" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if marker := msg.Header.Get(jetstream.MarkerReasonHeader); marker != "" {
		if marker == "MaxAge" || marker == "Purge" || marker == "Remove" {
			return nil, jetstream.ErrKeyNotFound
		}
		return nil, errors.New("invalid delivery operation marker")
	}
	if len(msg.Data) == 0 {
		return nil, errors.New("invalid delivery operation body")
	}
	return &operationValue{value: msg.Data, revision: msg.Sequence}, nil
}

func (s *Service) Status(ctx context.Context, operationID string) (Receipt, error) {
	return s.status(ctx, operationID, "")
}

func (s *Service) status(ctx context.Context, operationID, expectedFingerprint string) (Receipt, error) {
	if s == nil || !entityid.Valid(operationID) {
		return Receipt{}, ErrInvalid
	}
	e, err := s.getOperation(ctx, operationKey(operationID))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Receipt{}, ErrPending
	}
	if err != nil {
		return Receipt{}, err
	}
	var op operation
	if err := json.Unmarshal(e.Value(), &op); err != nil {
		return Receipt{}, fmt.Errorf("decode delivery status: %w", err)
	}
	if op.Intent.OperationID != operationID {
		return Receipt{}, ErrConflict
	}
	fingerprint, err := op.Intent.Fingerprint()
	if err != nil || fingerprint != op.Fingerprint {
		return Receipt{}, fmt.Errorf("%w: invalid durable operation fingerprint", ErrInvalid)
	}
	if expectedFingerprint != "" && fingerprint != expectedFingerprint {
		return Receipt{}, ErrConflict
	}
	if op.Receipt == nil {
		return Receipt{}, ErrPending
	}
	if op.Receipt.OperationID != operationID || op.Receipt.Fingerprint != fingerprint || op.Receipt.ArtifactDigest != op.Intent.ArtifactDigest || op.Receipt.ManifestDigest != op.Intent.ManifestDigest {
		return Receipt{}, fmt.Errorf("%w: invalid durable delivery receipt", ErrInvalid)
	}
	return *op.Receipt, nil
}

func (s *Service) StatusFor(ctx context.Context, intent Intent) (Receipt, error) {
	fingerprint, err := intent.Fingerprint()
	if err != nil {
		return Receipt{}, err
	}
	return s.status(ctx, intent.OperationID, fingerprint)

func (s *Service) PrepareArtifact(ctx context.Context, reader io.ReadSeeker, request ArtifactClaimRequest) (record ArtifactRecord, claim []byte, resultErr error) {
	if s == nil || reader == nil {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: missing artifact reader", ErrInvalid)
	}
	if err := request.validate(); err != nil || request.Cell != s.config.Cell {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: artifact target or source", ErrInvalid)
	}
	if s.config.ArtifactSigner == nil {
		return ArtifactRecord{}, nil, errors.New("artifact signer is not configured")
	}
	snapshot, size, digest, err := stageArtifact(ctx, reader)
	if err != nil {
		return ArtifactRecord{}, nil, err
	}
	defer func() {
		cleanupErr := discardStagedArtifact(snapshot)
		if cleanupErr != nil {
			if resultErr == nil {
				record = ArtifactRecord{}
				claim = nil
			}
			resultErr = errors.Join(resultErr, cleanupErr)
		}
	}()
	if size == 0 || size > MaxArtifactBytes {
		return ArtifactRecord{}, nil, fmt.Errorf("%w: artifact size must be 1..%d bytes", ErrInvalid, MaxArtifactBytes)
	}
	r := ArtifactRecord{SchemaVersion: SchemaVersion, Digest: digest, Source: request.Source, Cell: request.Cell, Role: request.Role, Environment: request.Environment, Size: size}
	r.ManifestDigest, err = r.calculatedManifestDigest()
	if err != nil {
		return ArtifactRecord{}, nil, err
	}
	if err := s.storeArtifact(ctx, snapshot, r); err != nil {
		return ArtifactRecord{}, nil, err
	}
	// Sign only after the bytes are stored: the claim's short validity must
	// cover its admission, not an upload over a slow operator link.
	envelope, err := s.config.ArtifactSigner.SignArtifact(ctx, r)
	if err != nil {
		return ArtifactRecord{}, nil, fmt.Errorf("sign artifact claim: %w", err)
	}
	return r, envelope, nil
}

// storeArtifact stores the staged bytes of r unless the store already holds
// them, and checks the stored object against r.
func (s *Service) storeArtifact(ctx context.Context, snapshot *os.File, r ArtifactRecord) error {
	exists, err := s.artifactExistsForUpload(ctx, r)
	if err != nil {
		return err
	}
	if exists {
		return nil
	}
	if _, err := snapshot.Seek(0, io.SeekStart); err != nil {
		return err
	}
	// Without a deadline every chunk ack gets only the JetStream default
	// timeout, which a slow operator link such as a bastion forward misses.
	uploadCtx, cancel := context.WithTimeout(ctx, artifactUploadTimeout)
	defer cancel()
	if _, err := s.artifacts.Put(uploadCtx, jetstream.ObjectMeta{Name: artifactKey(r.Digest)}, contextReader{uploadCtx, snapshot}); err != nil {
		if isArtifactStoreFullError(err) {
			return fmt.Errorf("store artifact: %w: %w", ErrArtifactStoreFull, err)
		}
		return fmt.Errorf("store artifact: %w", err)
	}
	return s.verifyArtifact(ctx, r)
}

func (s *Service) AcceptArtifactClaim(ctx context.Context, envelope []byte) (ArtifactRecord, error) {
	if s == nil || s.config.ArtifactVerifier == nil || s.config.AuthorizeArtifact == nil || len(envelope) == 0 || len(envelope) > MaxArtifactClaimBytes {
		return ArtifactRecord{}, fmt.Errorf("%w: artifact admission configuration or signed claim", ErrInvalid)
	}
	r, actor, err := s.config.ArtifactVerifier.VerifyArtifact(ctx, envelope)
	if err != nil || actor == "" || r.validate() != nil || r.Cell != s.config.Cell {
		return ArtifactRecord{}, fmt.Errorf("%w: artifact signature or cell", ErrInvalid)
	}
	if err := s.config.AuthorizeArtifact(ctx, actor, r); err != nil {
		return ArtifactRecord{}, err
	}
	// A collector that chose the object before this admission can no
	// longer delete it.
	if err := s.touchArtifact(ctx, r.Digest); err != nil {
		return ArtifactRecord{}, err
	}
	if err := s.verifyArtifact(ctx, r); err != nil {
		return ArtifactRecord{}, err
	}
	if err := s.persistArtifactAdmission(ctx, r, envelope, actor); err != nil {
		return ArtifactRecord{}, err
	}
	return r, nil
}

// touchArtifact pins a stored object for a new reference; see
// artifact.Touch.
func (s *Service) touchArtifact(ctx context.Context, digest string) error {
	if s.config.Conn == nil {
		return errors.New("artifact admission requires the controller's NATS connection")
	}
	js, err := s.config.Conn.JetStream()
	if err != nil {
		return err
	}
	err = artifact.Touch(ctx, js, ArtifactBucket, artifactKey(digest))
	if errors.Is(err, jetstream.ErrObjectNotFound) {
		return fmt.Errorf("%w: artifact object is not stored", ErrInvalid)
	}
	return err
}

// RetainArtifact validates the admitted bytes and touches their metadata before
// a caller commits a durable reference, fencing a concurrent GC deletion.
func (s *Service) RetainArtifact(ctx context.Context, record ArtifactRecord) error {
	resolved, err := s.ResolveAdmittedArtifact(ctx, record.Digest, record.Role, record.Environment)
	if err != nil {
		return err
	}
	if resolved != record {
		return ErrConflict
	}
	return s.touchArtifact(ctx, record.Digest)
}

